public:
  static SoundScriptManager *instance;
  static SoundScriptManager *inst() { return instance; }
  void pause();
  void unpause();
  SSEventId playSound(EventType, entity * = 0);
  SSEventId playEvent(EventType type, entity *e = 0, float = 0) { return playSound(type, e); }
};
